import json

def transform(grid):
    if not grid or not grid[0]:
        return grid

    # Find background and foreground colors
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    # Background is most common, foreground is less common non-zero
    sorted_colors = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    background = sorted_colors[0][0]
    foreground = sorted_colors[1][0] if len(sorted_colors) > 1 else 0

    result = [row[:] for row in grid]  # Make a copy

    # For each row, find pairs of foreground cells separated by exactly one background cell
    for row in result:
        i = 0
        while i < len(row) - 2:
            if (row[i] == foreground and row[i+1] == background and row[i+2] == foreground):
                row[i+1] = 2  # Fill between them
                i += 2  # Skip past this pair
            else:
                i += 1

    return result
